import {test,expect} from '@playwright/test';
import fs from 'node:fs';
test('video submission to real results, decisions, history and responsive views',async({page})=>{
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('/');await expect(page.getByRole('heading',{name:'协同任务运行总览'})).toBeVisible();
 fs.mkdirSync('../docs/screenshots',{recursive:true});
 await page.screenshot({path:'../docs/screenshots/01-overview.png',fullPage:true});
 await page.getByRole('button',{name:'新建分析任务'}).click();
 await page.getByLabel('任务名称',{exact:true}).fill('界面验证 · 视频分析');
 await page.getByRole('button',{name:'创建并运行'}).click();
 await expect(page.getByRole('heading',{name:'界面验证 · 视频分析',exact:true})).toBeVisible();
 await expect(page.locator('.task-summary').getByText('已完成',{exact:true})).toBeVisible({timeout:60000});
 await page.screenshot({path:'../docs/screenshots/02-workflow.png',fullPage:true});
 await page.getByRole('button',{name:'调度决策',exact:true}).click();
 await expect(page.getByRole('heading',{name:'算法输入与选择依据'})).toBeVisible();
 await expect(page.getByText('已选择',{exact:true})).toBeVisible();
 await page.screenshot({path:'../docs/screenshots/03-decision.png',fullPage:true});
 await page.getByRole('button',{name:'分析结果',exact:true}).click();
 await expect(page.getByText('100%',{exact:true})).toBeVisible();
 await expect(page.locator('.preview-grid img').first()).toBeVisible();
 await page.screenshot({path:'../docs/screenshots/04-results.png',fullPage:true});
 const [download]=await Promise.all([page.waitForEvent('download'),page.getByRole('link',{name:'下载结果及追溯记录'}).click()]);
 await download.saveAs('../docs/ui-export.json');
 const exported=JSON.parse(fs.readFileSync('../docs/ui-export.json','utf8'));expect(exported.status).toBe('SUCCEEDED');expect(exported.result.provenance).toHaveLength(6);
 await page.getByRole('button',{name:'事件与回放'}).click();
 await page.locator('input[type=range]').fill('3');
 await expect(page.getByText('历史回放模式',{exact:true})).toBeVisible();
 await page.getByRole('button',{name:'返回实时'}).click();
 await page.getByRole('button',{name:'执行节点',exact:true}).click();
 await expect(page.locator('.node-card')).toHaveCount(4);
 await page.screenshot({path:'../docs/screenshots/05-nodes.png',fullPage:true});
 await page.getByRole('button',{name:'工作流与能力',exact:true}).click();
 await page.getByRole('button',{name:'运行五类能力验证'}).click();
 await expect(page.locator('.cap-run').first().locator('.cap-grid .badge.succeeded')).toHaveCount(5,{timeout:30000});
 await page.screenshot({path:'../docs/screenshots/06-capabilities.png',fullPage:true});
 await page.getByRole('button',{name:'运行总览',exact:true}).click();
 await page.setViewportSize({width:390,height:844});
 await expect(page.getByRole('heading',{name:'协同任务运行总览'})).toBeVisible();
 await page.screenshot({path:'../docs/screenshots/07-mobile.png',fullPage:true});
 expect(errors).toEqual([]);
});
